CREATE TABLE document_files(id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(id) ON DELETE SET NULL, title TEXT NOT NULL, reference_json TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('source','draft')), format TEXT NOT NULL, sha256 TEXT NOT NULL, text_sha256 TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE document_notes(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document_files(id), category TEXT NOT NULL, content TEXT NOT NULL, scope_json TEXT NOT NULL, evidence_json TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL);
